<template>
  <div class="page-stack">
    <section class="hero compact"><div><span class="eyebrow">HISTORICAL SESSION METRICS</span><h1>历史会话指标计算</h1><p>选择 LiteLLM 普通会话，由 Judge 根据第一条用户 Prompt 分类，并计算工具、脚本、Skill、错误、重试和伪造输出指标。</p></div></section>
    <el-alert v-if="health.store?.status!=='ok'" type="warning" :closable="false" show-icon title="本地 SQLite 指标库尚未就绪" :description="health.store?.detail||'请检查项目数据目录的写入权限。'"/>
    <el-card shadow="never" class="panel"><el-form label-position="top" @submit.prevent="search"><div class="filters"><el-form-item label="时间范围"><el-date-picker v-model="timeRange" type="datetimerange" range-separator="至" :clearable="false"/></el-form-item><el-form-item label="End User"><el-input v-model="endUser" clearable/></el-form-item><el-form-item label="Session ID"><el-input v-model="sessionId" clearable/></el-form-item><el-form-item label="模型"><el-input v-model="model" clearable/></el-form-item><el-form-item label="查询"><el-button type="primary" native-type="submit" :loading="loading">搜索</el-button></el-form-item></div></el-form><div class="actions"><el-button type="primary" :disabled="!selected.length||health.store?.status!=='ok'" :loading="submitting" @click="calculateSelected">开始计算所选 {{selected.length}} 个会话</el-button><el-switch v-model="useJudge" active-text="使用 LLM Judge"/><span>点击会话查看已保存指标；每行“开始计算”可单独重算。</span></div></el-card>
    <el-card v-if="job" shadow="never" class="panel job-panel"><template #header><div class="job-title"><div><b>指标计算过程</b><code>{{job.job_id}}</code></div><el-tag :type="job.status==='completed'?'success':job.failed?'danger':'warning'">{{jobStatus(job.status)}}</el-tag></div></template><el-progress :percentage="jobProgress" :status="job.failed?'exception':job.status==='completed'?'success':undefined"/><div class="job-summary"><span>阶段：<b>{{jobPhase(job.phase)}}</b></span><span>进度：<b>{{job.completed||0}} / {{job.total||0}}</b></span><span v-if="job.current_session_id">当前会话：<code>{{job.current_session_id}}</code></span></div><div class="metric-events"><article v-for="event in job.events||[]" :key="event.sequence" :class="event.stage"><i/><div><b>{{event.message}}</b><span>{{eventDetail(event)}}</span></div><time>{{formatTime(event.timestamp)}}</time></article><el-empty v-if="!(job.events||[]).length" description="等待计算 Worker 返回过程事件" :image-size="44"/></div></el-card>
    <el-card shadow="never" class="panel"><el-table :data="rows" row-key="root_session_id" v-loading="loading" row-class-name="metric-row" @selection-change="selected=$event" @row-click="openMetrics">
      <el-table-column type="selection" width="48"/><el-table-column label="开始时间" width="175"><template #default="{row}">{{formatTime(row.started_at)}}</template></el-table-column><el-table-column label="Session ID" min-width="245" show-overflow-tooltip prop="root_session_id"/><el-table-column label="任务分类" min-width="175" show-overflow-tooltip><template #default="{row}">{{taskType(row.task_type)}}</template></el-table-column><el-table-column label="Agent" width="105"><template #default="{row}">{{row.agent||'未记录'}}</template></el-table-column><el-table-column label="模型" min-width="165" show-overflow-tooltip><template #default="{row}">{{row.models?.join('、')||'未记录'}}</template></el-table-column><el-table-column label="用户" width="125"><template #default="{row}">{{row.end_user||row.user_id||'未记录'}}</template></el-table-column><el-table-column label="交互" width="70" align="right" prop="interaction_count"/><el-table-column label="Token" width="95" align="right"><template #default="{row}">{{number(row.total_tokens)}}</template></el-table-column><el-table-column label="指标状态" width="125"><template #default="{row}"><el-tag :type="metricTag(row.metric_status)">{{metricStatus(row.metric_status)}}</el-tag></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="openMetrics(row)">查看指标</el-button><el-button link type="success" :loading="calculatingSession===row.root_session_id" @click.stop="calculateRows([row])">开始计算</el-button></template></el-table-column>
    </el-table><el-pagination v-if="total" v-model:current-page="page" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next" :page-sizes="[20,50,100]" :total="total" class="pagination" @current-change="load" @size-change="changeSize"/></el-card>

    <el-dialog v-model="detailVisible" width="860px" top="6vh" destroy-on-close append-to-body><template #header><div class="dialog-title"><div><span class="eyebrow">SESSION METRICS</span><b>会话指标</b><small>{{detailSession?.root_session_id}}</small></div><el-tag v-if="metricDetail" :type="metricTag(metricDetail.status)">{{metricStatus(metricDetail.status)}}</el-tag></div></template><div v-loading="detailLoading" class="metric-detail">
      <template v-if="metricDetail"><div class="detail-summary"><div><span>任务类型</span><b>{{taskType(metricDetail.task_type)}}</b></div><div><span>Agent</span><b>{{metricDetail.agent||'未记录'}}</b></div><div><span>模型</span><b>{{metricDetail.model||'未记录'}}</b></div><div><span>计算时间</span><b>{{formatTime(metricDetail.calculated_at)}}</b></div></div><div class="metric-grid"><article v-for="item in metricCards" :key="item.key"><span>{{item.label}}</span><b>{{item.value}}</b><small>{{item.help}}</small></article></div><el-divider content-position="left">Judge 与证据</el-divider><el-descriptions :column="2" border><el-descriptions-item label="分类 Judge">{{metricDetail.task_classification?.status||'未启用'}}</el-descriptions-item><el-descriptions-item label="分类理由">{{metricDetail.task_classification?.reason||metricDetail.task_classification?.error||'—'}}</el-descriptions-item><el-descriptions-item label="指标 Judge">{{metricDetail.judge?.status||'未启用'}}</el-descriptions-item><el-descriptions-item label="指标版本">{{metricDetail.metric_definition_version||'—'}}</el-descriptions-item><el-descriptions-item label="任务类型来源">{{metricDetail.task_type_source||'—'}}</el-descriptions-item><el-descriptions-item label="数据指纹"><code>{{metricDetail.source_fingerprint||'—'}}</code></el-descriptions-item></el-descriptions><el-divider content-position="left">原理图合理性指标</el-divider><section class="rationality" :class="`is-${rationality.status||'unknown'}`"><div class="rationality-head"><div><b>{{rationalityStatus(rationality.status)}}</b><small v-if="rationality.source_uuid">记录 {{rationality.source_uuid}}</small></div><el-tag :type="rationality.status==='completed'?'success':rationality.status==='not_found'?'info':'warning'">{{rationality.quality_level||'—'}}</el-tag></div><template v-if="rationality.status==='completed'"><div class="metric-grid rationality-grid"><article v-for="item in rationalityCards" :key="item.key"><span>{{item.label}}</span><b>{{item.value}}</b></article></div><p v-if="rationality.summary" class="rationality-summary">{{rationality.summary}}</p><ul v-if="rationality.issues?.length" class="issue-list"><li v-for="(issue,index) in rationality.issues" :key="index"><el-tag size="small" :type="issue.severity==='high'?'danger':issue.severity==='medium'?'warning':'info'">{{issue.severity||'info'}}</el-tag><b>{{issue.category||'问题'}}</b><span>{{issue.message}}</span></li></ul></template><el-alert v-else :closable="false" :type="rationality.status==='judge_unavailable'?'warning':'info'" :title="rationalityMessage(rationality)"/><el-descriptions v-if="rationality.source_record_id" :column="2" border class="source-meta"><el-descriptions-item label="匹配方式">{{matchType(rationality.matched_by)}}</el-descriptions-item><el-descriptions-item label="记录时间">{{formatTime(rationality.source_create_time)}}</el-descriptions-item><el-descriptions-item label="检查类型">{{rationality.check_type||'—'}}</el-descriptions-item><el-descriptions-item label="记录数量">{{number(rationality.record_count)}}</el-descriptions-item></el-descriptions><details v-if="rationality.result_text"><summary>查看原始 resultText</summary><pre>{{formatResultText(rationality.result_text)}}</pre></details></section><details><summary>查看完整指标 JSON</summary><pre>{{JSON.stringify(metricDetail,null,2)}}</pre></details></template>
      <el-empty v-else-if="!detailLoading" description="该会话尚未计算指标"><el-button type="primary" :loading="calculatingSession===detailSession?.root_session_id" @click="calculateRows([detailSession])">开始计算指标</el-button></el-empty>
    </div><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="metricDetail" type="primary" :loading="calculatingSession===detailSession?.root_session_id" @click="calculateRows([detailSession])">重新计算</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {createMetricJob,fetchMetricDetail,fetchMetricHealth,fetchMetricJob,fetchMetricSessions} from '../api'
const now=Date.now(),timeRange=ref([new Date(now-24*60*60*1000),new Date(now)]),endUser=ref(''),sessionId=ref(''),model=ref(''),rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),selected=ref([]),loading=ref(false),submitting=ref(false),useJudge=ref(true),health=ref({}),job=ref(null),detailVisible=ref(false),detailLoading=ref(false),detailSession=ref(null),metricDetail=ref(null),calculatingSession=ref('')
let pollTimer
const params=()=>({start_time:timeRange.value[0].toISOString(),end_time:timeRange.value[1].toISOString(),end_user:endUser.value||undefined,session_id:sessionId.value||undefined,model:model.value||undefined,limit:pageSize.value,offset:(page.value-1)*pageSize.value})
async function load(){loading.value=true;try{const data=await fetchMetricSessions(params());rows.value=data.conversations||[];total.value=data.total||0}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{loading.value=false}}
async function search(){page.value=1;await load()} async function changeSize(){page.value=1;await load()}
async function calculateSelected(){await calculateRows(selected.value)}
async function calculateRows(items){const valid=(items||[]).filter(Boolean);if(!valid.length)return;submitting.value=true;if(valid.length===1)calculatingSession.value=valid[0].root_session_id;try{job.value=await createMetricJob({session_ids:valid.map(row=>row.root_session_id),start_time:timeRange.value[0].toISOString(),end_time:timeRange.value[1].toISOString(),use_llm_judge:useJudge.value});ElMessage.success('指标计算任务已开始');poll()}catch(error){ElMessage.error(error.response?.data?.detail||error.message);calculatingSession.value=''}finally{submitting.value=false}}
async function poll(){clearTimeout(pollTimer);if(!job.value)return;try{job.value=await fetchMetricJob(job.value.job_id)}catch{}if(['queued','running'].includes(job.value?.status))pollTimer=setTimeout(poll,1500);else{calculatingSession.value='';await load();if(detailVisible.value&&detailSession.value)await loadMetricDetail(detailSession.value)}}
async function openMetrics(row){detailSession.value=row;detailVisible.value=true;await loadMetricDetail(row)}
async function loadMetricDetail(row){detailLoading.value=true;metricDetail.value=null;try{metricDetail.value=await fetchMetricDetail(row.root_session_id)}catch(error){if(error.response?.status!==404)ElMessage.error(error.response?.data?.detail||error.message)}finally{detailLoading.value=false}}
const jobProgress=computed(()=>Number(job.value?.progress??(job.value?.total?Math.round(((job.value.completed||0)+(job.value.failed||0))/job.value.total*100):0)))
const metricCards=computed(()=>{const m=metricDetail.value?.metrics||{};return[{key:'tool',label:'工具调用成功率',value:percent(m.tool_success_rate),help:`成功 ${number(m.tool_success_count)} / 共 ${number(m.tool_call_count)}`},{key:'skill',label:'Skill 轨迹完成度',value:percent(m.skill_completeness),help:`完成 ${number(m.skill_completed_steps)} / ${number(m.skill_required_steps)} 步`},{key:'errors',label:'任务报错次数',value:number(m.error_count),help:`未恢复 ${number(m.unrecovered_error_count)}`},{key:'retries',label:'任务重试次数',value:number(m.retry_attempt_count),help:`成功恢复 ${number(m.recovered_error_count)}`},{key:'fabrication',label:'疑似伪造输出',value:number(m.suspected_fabrication_count),help:m.confirmed_fabrication_count==null?'未做确认性判定':`确认 ${number(m.confirmed_fabrication_count)}`},{key:'script',label:'脚本调用成功率',value:percent(m.script_success_rate),help:`成功 ${number(m.script_success_count)} / 共 ${number(m.script_call_count)}`} ]})
const rationality=computed(()=>metricDetail.value?.schematic_rationality||{status:'not_found'})
const rationalityCards=computed(()=>{const m=rationality.value.metrics||{};return[{key:'overall_score',label:'综合质量',value:score(m.overall_score)},{key:'electrical_correctness',label:'电气正确性',value:score(m.electrical_correctness)},{key:'component_selection',label:'器件选型',value:score(m.component_selection)},{key:'signal_integrity',label:'信号完整性',value:score(m.signal_integrity)},{key:'power_integrity',label:'电源完整性',value:score(m.power_integrity)},{key:'protection_completeness',label:'保护完整性',value:score(m.protection_completeness)},{key:'layout_readability',label:'布局可读性',value:score(m.layout_readability)},{key:'unrouted_net_count',label:'未布线网络',value:number(m.unrouted_net_count)},{key:'overlap_count',label:'重叠数量',value:number(m.overlap_count)},{key:'erc_error_count',label:'ERC 错误',value:number(m.erc_error_count)},{key:'warning_count',label:'告警数量',value:number(m.warning_count)}]})
const metricStatus=value=>({not_calculated:'未计算',rules_completed:'规则已完成',rules_completed_judge_unavailable:'规则完成 / Judge不可用',completed:'已完成',failed:'失败'}[value]||value||'未知'),metricTag=value=>String(value||'').includes('completed')?'success':value==='failed'?'danger':'info',jobStatus=value=>({queued:'排队中',running:'计算中',completed:'已完成',completed_with_errors:'完成但有失败'}[value]||value),jobPhase=value=>({queued:'等待调度',loading_session:'读取会话',rule_metrics:'规则指标计算',task_classification:'首条 Prompt 分类',llm_judge:'LLM Judge 分析',schematic_rationality:'原理图合理性分析',saving_metrics:'写入本地指标库',completed:'任务结束'}[value]||value||'准备中'),taskType=value=>({block_to_schematic:'框图生成原理图',block_to_signal_list:'框图生成信号接口列表',signal_list_to_schematic:'信号接口列表生成原理图',schematic_apply_to_tianshu:'原理图应用到天枢',schematic_adjustment:'原理图调整任务',other_schematic:'其他原理图任务',other:'其他任务'}[value]||value||'未分类')
const rationalityStatus=value=>({completed:'分析完成',not_found:'未找到合理性分析记录',judge_unavailable:'Judge 不可用',judge_disabled:'未启用 Judge'}[value]||value||'未知状态')
const rationalityMessage=value=>value.status==='not_found'?'该会话及其评测运行 ID 在 HDschematicRationalityCollection 中没有已完成记录。':value.error||rationalityStatus(value.status)
const matchType=value=>({root_session_id:'真实 Session ID',evaluation_run_id:'评测运行 ID'}[value]||value||'—')
const formatResultText=value=>{if(typeof value!=='string')return JSON.stringify(value,null,2);try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}
const eventDetail=event=>[event.session_id?`会话 ${event.session_id}`:'',event.chunk_total?`分片 ${event.chunk_index}/${event.chunk_total}`:'',event.interaction_count!=null?`${event.interaction_count} 轮交互`:'',event.task_type?taskType(event.task_type):'',event.metric_status?metricStatus(event.metric_status):'',event.detail||''].filter(Boolean).join(' · ')
const formatTime=value=>value?new Date(value).toLocaleString('zh-CN'):'—',number=value=>value==null?'—':Number(value).toLocaleString(),percent=value=>value==null?'—':`${Number(value).toFixed(1)}%`,score=value=>value==null?'—':`${Number(value).toFixed(1)} / 100`
onMounted(async()=>{try{health.value=await fetchMetricHealth()}catch{}await load()});onBeforeUnmount(()=>clearTimeout(pollTimer))
</script>

<style scoped>
.filters{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 100px;align-items:end;gap:12px}.filters :deep(.el-form-item){margin:0}.filters :deep(.el-date-editor){width:100%}.filters .el-button{width:100%}.actions{display:flex;align-items:center;gap:18px;margin-top:16px}.actions span{color:var(--muted);font-size:12px}.pagination{display:flex;justify-content:flex-end;margin-top:18px}.metric-row{cursor:pointer}.job-title,.job-summary{display:flex;align-items:center;justify-content:space-between;gap:14px}.job-title>div{display:flex;flex-direction:column;gap:5px}.job-panel code{color:var(--muted)}.job-summary{justify-content:flex-start;flex-wrap:wrap;margin:13px 0;color:var(--muted);font-size:12px}.job-summary span+span{padding-left:14px;border-left:1px solid var(--line)}.metric-events{display:grid;max-height:330px;overflow:auto;border:1px solid var(--line);border-radius:9px}.metric-events article{display:grid;grid-template-columns:10px minmax(0,1fr) auto;align-items:start;gap:11px;padding:11px 13px;border-bottom:1px solid var(--line);background:var(--surface)}.metric-events article:last-child{border-bottom:0}.metric-events i{width:8px;height:8px;margin-top:5px;border-radius:50%;background:#25a66a}.metric-events article.session_failed i,.metric-events article.llm_judge_unavailable i,.metric-events article.schematic_rationality_judge_unavailable i{background:#d84a4a}.metric-events article.llm_judge_chunk_started i,.metric-events article.loading_session i,.metric-events article.schematic_rationality_loading i{background:#d59b2b}.metric-events article>div{display:flex;flex-direction:column;gap:4px}.metric-events article span,.metric-events time{color:var(--muted);font-size:11px}.metric-events time{white-space:nowrap}.dialog-title{display:flex;align-items:center;justify-content:space-between;gap:15px}.dialog-title>div{display:flex;flex-direction:column;gap:4px}.dialog-title small{color:var(--muted)}.metric-detail{min-height:280px;max-height:70vh;overflow:auto}.detail-summary,.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.detail-summary>div,.metric-grid article{display:flex;flex-direction:column;gap:5px;padding:14px;border:1px solid var(--line);border-radius:9px;background:var(--surface-2)}.detail-summary span,.metric-grid span,.metric-grid small{color:var(--muted);font-size:11px}.metric-grid{grid-template-columns:repeat(3,1fr);margin-top:12px}.metric-grid b{font-size:23px}.rationality{display:grid;gap:12px}.rationality-head{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid var(--line);border-radius:9px}.rationality-head>div{display:flex;flex-direction:column;gap:4px}.rationality-head small{color:var(--muted)}.rationality-grid{grid-template-columns:repeat(4,1fr);margin:0}.rationality-grid b{font-size:17px}.rationality-summary{margin:0;padding:12px 14px;border-left:3px solid var(--brand);background:var(--surface-2)}.issue-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}.issue-list li{display:grid;grid-template-columns:auto auto 1fr;align-items:start;gap:8px;padding:10px;border-bottom:1px solid var(--line)}.source-meta{margin-top:2px}.metric-detail details{margin-top:18px}.metric-detail summary{cursor:pointer;color:var(--brand)}.metric-detail pre{max-height:420px;overflow:auto;padding:14px;border-radius:8px;background:#151a18;color:#e7eee9;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:1000px){.filters{grid-template-columns:1fr 1fr}.filters>:last-child{grid-column:1/-1}.detail-summary,.metric-grid,.rationality-grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.filters,.detail-summary,.metric-grid,.rationality-grid{grid-template-columns:1fr}.filters>:last-child{grid-column:auto}.actions{align-items:flex-start;flex-direction:column}.metric-events article{grid-template-columns:10px 1fr}.metric-events time{grid-column:2}.issue-list li{grid-template-columns:auto 1fr}.issue-list li span{grid-column:1/-1}}
</style>
